        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'xs', 'weight' => 'bold', 'class' => 'leading-4', 'children' => (string) $c_4])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'class' => og_s(og_cnv(['w-full px-2 text-muted-foreground', og_preset('blocks/presets/defaults.json', ['news', 'strip'])])), 'attrs' => og_attrs(['data-slot', 'news-date']), 'children' => (string) $c_5])|noescape}
  {/capture}
  {=og_include('compose/Block.latte', ['tag' => 'article', 'class' => og_s(og_cnv(['flex flex-col gap-2 overflow-hidden rounded p-0 inset-ring inset-ring-border', og_preset('blocks/presets/defaults.json', ['news', 'card'])])), 'attrs' => og_attrs(['data-layout', $v_layout, 'data-meta', 'news', 'data-slot', 'item']), 'children' => (string) $c_6])|noescape}
{else}
