      {capture $c_7}
        {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_post, ['title']), 'src' => og_get($v_post, ['image']), 'className' => og_cnv(['h-full'])]])|noescape}
      {/capture}
